    post_api_auth_refresh: {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        requestBody?: never;
        responses: {
            /** @description Nouveau JWT (durée de vie 3600 s) ; le cookie `repas_refresh` est remplacé */
            200: {
                headers: {
                    /** @description Nouveau refresh token, `HttpOnly; Secure; SameSite=Strict; Path=/api/auth` */
                    "Set-Cookie"?: string;
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        token?: string;
                    };
                };
            };
            /** @description Cookie absent, inconnu, expiré, déjà utilisé, compte désactivé ou mot de passe changé depuis : sans précision. Le cookie est effacé ; le client réessaie une fois (course entre onglets) avant de renvoyer à la connexion */
            401: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
            /** @description Trop de rafraîchissements depuis cette adresse (60 par 10 minutes) */
            429: {
                headers: {
                    [name: string]: unknown;
                };
                content?: never;
            };
        };
    };
